import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"5、【需】 乾下坎上","description":"子夏易传 - 5、【需】 乾下坎上","frontmatter":{"title":"5、【需】 乾下坎上","description":"子夏易传 - 5、【需】 乾下坎上"},"headers":[],"relativePath":"zh/classics/zixia/007.md","filePath":"zh/classics/zixia/007.md"}'),i={name:"zh/classics/zixia/007.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_5、【需】-乾下坎上" tabindex="-1">5、【需】 乾下坎上 <a class="header-anchor" href="#_5、【需】-乾下坎上" aria-label="Permalink to “5、【需】 乾下坎上”">​</a></h1><p>卦辞：需，有孚光，亨贞吉，利涉大川。</p><p>彖曰：需，須也，險在前也，剛健而不陷其義，不困窮矣。需有孚光，亨貞吉，位乎天位以正中也。利涉大川，往有功也。</p><p>子夏：需，待也。剛居於尊，安於險之道也。能制下，健以為用，君子待命而已，不可自任，則剛健終不陷也。君子觀其爲而動之，其義豈窮哉。五以險德而位於天，雖非坦道，强毅而制下也。剛中而有孚也。獲剛健之臣而不敢不説，則不勞而待其功矣。故光通而貞吉，復何險之有哉。是以利涉大川，而無險不濟也。文王君人也，得九五之位。仲尼位下也，居君子之事合，兩而待之，則上待下之能，下待上之命。觀是需之情可見矣。</p><p>象曰：雲上于天，需。君子以飲食宴樂。</p><p>子夏：澤來矣，君子待命而不勞於慮，而得其治也，飲食宴樂而已。</p><p>初九，需于郊，利用恒，无咎。象曰：需于郊，不犯難行也。利用恒，无咎。未失常也。</p><p>子夏：郊逺者也，未履其位，行不犯難也。用其常不失其素矣。</p><p>九二，需于沙，小有言，終吉。象曰：需于沙，衍在中也。雖小有言，以吉終也。</p><p>子夏：行逺也，沙，邇乎水，剛履其位，敵對於五，五非敵也。可以待也。君子之道，無執也。與時而行也。得其中者，雖小有言，吉終而已矣。</p><p>九三，需于泥，致宼至。象曰：需于泥，災在外也。自我致宼，敬愼不敗也。</p><p>子夏：上險可犯也。剛以在上，待命於泥，逼難而濡難，猶外矣。我致之，而宼至，敬愼之，不敗也。</p><p>六四，需于血，出自穴。象曰：需于血，順以聽也。</p><p>子夏：剛險居上，而承之難，從事者也。動而見傷矣。坎隂處下，幽穴之物，而今升之，待陽之運而出，難也。則不可不順以聽之。</p><p>九五，需于酒，食貞吉。象曰：酒食貞吉以中正也。</p><p>子夏：剛德中正，施令而治者也。治事已獲衆之奉，待其酒食而已。</p><p>上六，入于穴，有不速之客，三人來，敬之，終吉。象曰：不速之客來，敬之，終吉。雖不當位，未大失也。</p><p>子夏：需坎上也，道之終則反覆也，入于穴矣。乾覆其上，三爻來而不假待也。知道之終能固其所，而敬為主，雖不得其位能吉其終也。</p>',18)])])}const h=a(i,[["render",r]]);export{f as __pageData,h as default};
